local config = {
  ui_story_30540401_1_dialog_content = "It's okay. Just speak your mind.",
  ui_story_30540401_2_dialog_content = "It's nothing, actually. You just got back from a full day of work, so I'm wondering if there's anything I can do for you.",
  ui_story_30540401_3_dialog_content = "Are you bothered by that thought of mine?",
  ui_story_30540401_4_option_content = "I'm just not used to it, is all",
  ui_story_30540401_5_dialog_content = "How should I put it... I tend to run into people \"<color=#FFB400>with unique attitude</color>\" very often.",
  ui_story_30540401_6_dialog_content = "To put it simply, I'm so used to being bullied that I'm not accustomed to others treating me so nicely.",
  ui_story_30540401_7_dialog_content = "Oh, I appreciate it very much, of course!",
  ui_story_30540401_8_option_content = "Not at all. I'm very touched!",
  ui_story_30540401_9_dialog_content = "Caring friends are very hard to come by!",
  ui_story_30540401_10_dialog_content = "Honestly, I thought caring people were a rare breed these days.",
  ui_story_30540401_11_dialog_content = "You're not old enough to speak like you're out of loop with the time...",
  ui_story_30540401_12_dialog_content = "No, I'm not too old, but am out of loop. I mean, I did live in a Colossus by myself for a long time...",
  ui_story_30540401_13_dialog_content = "That's too... Anyway, I want to do something for you!",
  ui_story_30540401_14_dialog_content = "I appreciate the thought very much already!",
  ui_story_30540401_15_dialog_content = "I believe a mail came in for me while I was out, though. Let me go get it and I'll be right back.",
  ui_story_30540401_16_dialog_content = "Oh, no need. I've gotten it for you!",
  ui_story_30540401_17_dialog_content = "You got my mail for me? That's so nice and caring of you!",
  ui_story_30540401_18_dialog_content = "Ahem. Well, that's because I happened to hear Miss Vice mentioned about it, and I knew you weren't around, so...",
  ui_story_30540401_19_dialog_content = "OK. Let me go read it.",
  ui_story_30540401_20_dialog_content = "I'll get it for you right away if you want to read it now! Please sit still and don't go anywhere!",
  ui_story_30540401_21_dialog_content = "Whoa, it was just a casual remark and off she went!",
  ui_story_30540401_22_dialog_content = "Here's your letter!",
  ui_story_30540401_23_dialog_content = "Uh, thanks!",
  ui_story_30540401_24_dialog_content = "Oh, let me get you something to drink. You must be thirsty from the trip!",
  ui_story_30540401_25_dialog_content = "What would you like, coffee or tea?",
  ui_story_30540401_26_dialog_content = "I can use a little pick-me-up. How about...",
  ui_story_30540401_27_option_content = "Tea",
  ui_story_30540401_28_dialog_content = "Tea is my specialty! You prefer tea over coffee, just like the City Lord!",
  ui_story_30540401_29_option_content = "Coffee",
  ui_story_30540401_30_dialog_content = "Coffee is a great choice! I like to drink coffee! It calms your nerves!",
  ui_story_30540401_31_dialog_content = "Here's your drink, PlayerName!",
  ui_story_30540401_32_dialog_content = "Hey!",
  ui_story_30540401_33_dialog_content = "I'm sorry! I didn't mean to spill it on you!",
  ui_story_30540401_34_dialog_content = "It's all right. It's just a little. I can just wipe it off.",
  ui_story_30540401_35_dialog_content = "But I got to ask, why are you so enthusiastic about helping out today?",
  ui_story_30540401_36_dialog_content = "Well... I've been learning how to care for people lately...",
  ui_story_30540401_37_dialog_content = "Oh? Why that all of a sudden?",
  ui_story_30540401_38_dialog_content = "Because... As a <color=#FFB400>Nightwatch</color>, I must be good in everything!",
  ui_story_30540401_39_dialog_content = "There hasn't been anything official to handle lately, so I made myself a plan to become a better person.",
  ui_story_30540401_40_option_content = "What's a Nightwatch?",
  ui_story_30540401_41_dialog_content = "A Nightwatch is the City Lord's <color=#FFB400>secret guards</color>.",
  ui_story_30540401_42_dialog_content = "I may be a guard, but not the actual kind that protects the City Lord, since he's far more powerful than I am.",
  ui_story_30540401_43_dialog_content = "In other words, we're special ops that go around at night collecting information or carrying out assassinations.",
  ui_story_30540401_44_dialog_content = "Did I just stumble upon a terrifying secret?",
  ui_story_30540401_45_dialog_content = "We may be the secret guards, but it's not a secret that we exist.",
  ui_story_30540401_46_dialog_content = "Many people already know we exist but are just unsure of who the members are.",
  ui_story_30540401_47_dialog_content = "But I now know that you're one of them...",
  ui_story_30540401_48_option_content = "A better person? How much better?",
  ui_story_30540401_49_dialog_content = "At least as good as <color=#FFB400>Ms. Blanc</color>!",
  ui_story_30540401_50_dialog_content = "She could handle all sorts of missions with ease, and could maintain her grace even during assassinations!",
  ui_story_30540401_51_dialog_content = "Did I just stumble upon a terrifying secret?",
  ui_story_30540401_52_dialog_content = "It's actually not a secret. Ms. Blanc would talk about it herself, just not publicly.",
  ui_story_30540401_53_dialog_content = "But you just made it known to me.",
  ui_story_30540401_54_dialog_content = "It's... no biggie. You have enough clout to find out eventually, anyway.",
  ui_story_30540401_55_dialog_content = "Do me a favor, don't mention you heard it from me.",
  ui_story_30540401_56_dialog_content = "Okay.",
  ui_story_30540401_57_dialog_content = "It's about time I <color=#FFB400>get back to my room</color>. Anything else?",
  ui_story_30540401_58_dialog_content = "Why? Can't you just rest here?",
  ui_story_30540401_59_dialog_content = "I do need personal space.",
  ui_story_30540401_60_dialog_content = "Okay... Would you mind answering a question before you leave?",
  ui_story_30540401_61_dialog_content = "How'd you rate my performance?",
  ui_story_30540401_62_option_content = "Pretty good I'd say.",
  ui_story_30540401_63_dialog_content = "In other words, you're leaning toward \"satisfied\"?",
  ui_story_30540401_64_dialog_content = "\"Satisfied\" is an awkward way of putting it, but I do think you were very considerate.",
  ui_story_30540401_65_option_content = "Hmm. Maybe it could be better?",
  ui_story_30540401_66_dialog_content = "It's because I spilled a drink on you, isn't it?",
  ui_story_30540401_67_dialog_content = "No. That's nothing. Don't worry about it.",
  ui_story_30540401_68_dialog_content = "It's normal to make mistakes once in a while.",
  ui_story_30540401_69_dialog_content = "But what should I do if I accidentally made a mistake?",
  ui_story_30540401_70_dialog_content = "Just apologize properly.",
  ui_story_30540401_71_dialog_content = "Oh, I see... Would you mind hearing about the mistakes I made then?",
  ui_story_30540401_72_dialog_content = "Actually, when I deliver the letter to your <color=#FFB400>room</color>...",
  ui_story_30540401_73_dialog_content = "What about it? I don't see anything wrong with the letter.",
  ui_story_30540401_74_dialog_content = "It's not the letter. When I went into your room, I thought it looked a little messy...",
  ui_story_30540401_75_dialog_content = "True. I was in too big of a hurry today to tidy it up.",
  ui_story_30540401_76_dialog_content = "I thought since I got nothing better to do, I'd clean it up for you...",
  ui_story_30540401_77_dialog_content = "<color=#FFB400>But I made the room an even bigger mess.</color>",
  ui_story_30540401_78_dialog_content = "...",
  ui_story_30540401_79_dialog_content = "...",
  ui_story_30540401_80_dialog_content = "<size=45>Huh?</size>",
  ui_story_30540401_81_dialog_content = "I wanted to tidy it up before you got back, but you came back earlier than expected! I'm very sorry!",
  ui_story_30540401_82_dialog_content = "Uh, can you tell me what you did...?",
  ui_story_30540401_83_dialog_content = "I tidied up for a bit, sanitized the room with the lantern's power, then ironed your clothes...",
  ui_story_30540401_84_dialog_content = "So, what made the room messier?",
  ui_story_30540401_85_dialog_content = "A few of your clothes are ruined, and the floor and walls... are a little cracked.",
  ui_story_30540401_86_dialog_content = "I'm very sorry!",
  ui_story_30540401_87_dialog_content = "Now I get why you're so eager to help me.",
  ui_story_30540401_88_dialog_content = "It's to make up for wrecking my room, right?",
  ui_story_30540401_89_dialog_content = "Unfortunately, yes.",
  ui_story_30540401_90_dialog_content = "*Inhaling deeply and forcing a smile*",
  ui_story_30540401_91_dialog_content = "It's all right. You're going out of your way to apologize, so I...",
  ui_story_30540401_92_dialog_content = "Nah, I'm not mad at you.",
  ui_story_30540601_1_dialog_content = "I'm back...",
  ui_story_30540601_2_dialog_content = "\"I love work, yes I do!\"",
  ui_story_30540601_3_dialog_content = "\"I love work. How 'bout you?\"",
  ui_story_30540601_4_dialog_content = "Why are my Fireflies singing such a weird song? Wait... Are they... Dancing?!",
  ui_story_30540601_5_dialog_content = "Welcome back! Please place your coat here!",
  ui_story_30540601_6_dialog_content = "Oh, and please wipe your shoes before entering, if you want to keep them on.",
  ui_story_30540601_7_dialog_content = "Fireflies! Shoe cloth!",
  ui_story_30540601_8_dialog_content = "\"Please use this cloth to wipe your shoes.\"",
  ui_story_30540601_9_dialog_content = "Oh hey, you're wearing your new outfit! But, uh... What exactly is going on here?",
  ui_story_30540601_10_dialog_content = "I'm in middle of <color=#FFB400>work</color>, PlayerName.",
  ui_story_30540601_11_dialog_content = "\"Work\"? Why do you guys keep talking about \"work\"...",
  ui_story_30540601_12_dialog_content = "Well, actually...",
  ui_story_30540601_13_dialog_content = "A trim and well-ironed uniform, and a piping-hot cup of coffee. A perfect start to a hard day's work—",
  ui_story_30540601_14_dialog_content = "*Sigh* Only... It's my day off today.",
  ui_story_30540601_15_dialog_content = "Is everything okay, Miss Nadine?",
  ui_story_30540601_16_dialog_content = "Everything is perfectly fine. It's just that I'm usually busy at work, and have gotten used to keeping occupied all the time.",
  ui_story_30540601_17_dialog_content = "But suddenly having a day off with nothing to do... Feels a little strange for me.",
  ui_story_30540601_18_dialog_content = "You're so hardworking and dedicated, Nadine! And you love your work, too!",
  ui_story_30540601_19_dialog_content = "If only...",
  ui_story_30540601_20_dialog_content = "Hmm? Is there something on your mind, Vice?",
  ui_story_30540601_21_dialog_content = "Ehehe... I was just thinking... If only you could give me a hand with something, I'd be really grateful!",
  ui_story_30540601_22_dialog_content = "What is it? I'm always willing to help, as long as it's within my capacity to do so.",
  ui_story_30540601_23_dialog_content = "Really?",
  ui_story_30540601_24_dialog_content = "Well, you see... I just got an urgent mission request, and I have no choice but to leave right away.",
  ui_story_30540601_25_dialog_content = "But today is my turn to be on patrol, and PlayerName still hasn't come back...",
  ui_story_30540601_26_dialog_content = "So, could you please help me manage the Colossus?",
  ui_story_30540601_27_dialog_content = "If you have any questions, I made this \"patrol duty manual\" that you can refer to whenever you want!",
  ui_story_30540601_28_dialog_content = "I see... Understood. Leave it to me, and be safe on your mission.",
  ui_story_30540601_29_dialog_content = "You're the best! Thank you so much!",
  ui_story_30540601_30_dialog_content = "Oh, and someone will be delivering a package soon. Could you please remember to receive it?",
  ui_story_30540601_31_dialog_content = "It's a shipment of new clothing.",
  ui_story_30540601_32_dialog_content = "One of them is a surprise for you from PlayerName, so you're more than welcome to open it and take a look!",
  ui_story_30540601_33_dialog_content = "Anyway, I should get going! The Colossus is in your hands now!",
  ui_story_30540601_34_dialog_content = "Leave it to me. I'll do my best!",
  ui_story_30540601_35_dialog_content = "Hmm... The manual says that the Fireflies handle most of the cleaning on the Colossus. In that case...",
  ui_story_30540601_35X_dialog_content = "Maybe I should have a cup of coffee to perk myself up a little?",
  ui_story_30540601_36_dialog_content = "<color=#e8d9bb>Zoom!</color>",
  ui_story_30540601_38_dialog_content = "I wasn't paying attention when that Firefly flew past me, so I slipped and fell...",
  ui_story_30540601_39_dialog_content = "And spilled coffee all over myself. I had no choice but to change into this outfit.",
  ui_story_30540601_40_dialog_content = "It's so pretty... I swear I won't get this one dirty! Can I really wear it, though?",
  ui_story_30540601_41_dialog_content = "Of course you can. I was planning on giving it to you as a gift, anyways.",
  ui_story_30540601_42_dialog_content = "Wonderful!",
  ui_story_30540601_43_dialog_content = "Anyways, what's the matter with the Fireflies? They were all singing and dancing just now...",
  ui_story_30540601_44_dialog_content = "I adjusted their settings according to the manual that Vice left me.",
  ui_story_30540601_45_dialog_content = "What you just saw was their standby formation.",
  ui_story_30540601_46_dialog_content = "And that weird song...",
  ui_story_30540601_47_dialog_content = "I sing it to myself all the time. Hopefully, it will motivate our friends to do an even better job on the Colossus!",
  ui_story_30540601_48_dialog_content = "Ugh, why do you keep bringing up \"work\" and \"jobs\"...",
  ui_story_30540601_49_dialog_content = "Oh, that's right! I still need to finish inspecting the rooms!",
  ui_story_30540601_50_dialog_content = "\"Inspecting\"?",
  ui_story_30540601_51_dialog_content = "Oh, maid!",
  ui_story_30540601_52_dialog_content = "Understood.",
  ui_story_30540601_53_dialog_content = "Changing Modes: Sweeper.",
  ui_story_30540601_54_dialog_content = "Room inspections complete. The contraband has been confiscated.",
  ui_story_30540601_55_dialog_content = "C...Contraband?",
  ui_story_30540601_56_dialog_content = "That's right! Vice's patrol manual has a number of rules to follow.",
  ui_story_30540601_57_dialog_content = "\"In order to ensure the safety of all passengers aboard the Colossus, the following items are not allowed on board:\"",
  ui_story_30540601_58_dialog_content = "\"Flammables or explosives...\"",
  ui_story_30540601_59_dialog_content = "Suddenly, I can't help but think of all the people who break this rule regularly.",
  ui_story_30540601_60_dialog_content = "\"Dangerous weapons and bladed objects...\"",
  ui_story_30540601_61_dialog_content = "Again, I can't help but think of all the people who break this rule regularly, either...",
  ui_story_30540601_62_dialog_content = "See? I've only finished reading the second rule, and you can probably name a dozen rule breakers!",
  ui_story_30540601_63_dialog_content = "There is no respect between people if there is no respect for the rules, you know?",
  ui_story_30540601_64_dialog_content = "Sure, but...",
  ui_story_30540601_65_dialog_content = "Maid! Let's move on!",
  ui_story_30540601_66_dialog_content = "I should tell you, even Vice doesn't enforce these rules very strictly...",
  ui_story_30540601_66X_dialog_content = "Uh... Hello? Where'd she go?",
  ui_story_30540601_67_dialog_content = "<color=#e8d9bb>Ten minutes later...</color>",
  ui_story_30540601_68_dialog_content = "Where are my speakers? Did somebody move them without my permission?",
  ui_story_30540601_69_dialog_content = "Where did my cute, little saw go?",
  ui_story_30540601_70_dialog_content = "What are you doing here?",
  ui_story_30540601_71_dialog_content = "Regina... Were you the one who took my saw?",
  ui_story_30540601_72_dialog_content = "What are you babbling about? You're the one who stole my speakers, aren't you?",
  ui_story_30540601_73_dialog_content = "Jealous that they're even taller than you or something?!",
  ui_story_30540601_74_dialog_content = "Hah? You mean those crappy speakers used for opening acts? I wouldn't dream of touching them in a million years!",
  ui_story_30540601_75_dialog_content = "What was that? You tryin' to pick a fight?!",
  ui_story_30540601_76_dialog_content = "W-Wait you two, just calm down! You're both missing some of your belongings, aren't you? Could it be...",
  ui_story_30540601_77_dialog_content = "You think I'm scared of you? Let's settle this once and for all! Right here, right now!",
  ui_story_30540601_78_dialog_content = "You can be the judge, PlayerName!",
  ui_story_30540601_79_dialog_content = "Why are you still fighting?! I refuse to have any part in this...!",
  ui_story_30540601_80_dialog_content = "Then allow me to act as the judge!",
  ui_story_30540601_81_dialog_content = "Eh? That voice... Isn't that...?",
  ui_story_30540601_82_dialog_content = "First! Act as a beacon to guide others forward!",
  ui_story_30540601_83_dialog_content = "Second! Ensure the uniform is ironed and creases are sharp!",
  ui_story_30540601_84_dialog_content = "Third! Maintain a diligent work ethic at all times!",
  ui_story_30540601_85_dialog_content = "\"<color=#FFB400>Patrol Captain</color>\" Nadine is here to perform her duties, and preside over this fateful match!",
  ui_story_30540601_86_dialog_content = "... There are so many things wrong with this situation, I don't even know where to start!",
  ui_story_30540601_87_dialog_content = "Anyways, could you please explain what that introduction was all about?",
  ui_story_30540601_88_dialog_content = "Well, one of the rules in Vice's manual is to \"preserve a sense of love and harmony aboard the Colossus\"...",
  ui_story_30540601_89_dialog_content = "What does that have to do with your crazy introduction just now?!",
  ui_story_30540601_90_dialog_content = "The manual also states that \"while mediating between two conflicting parties, remember to introduce yourself as the mediator to both sides.\"",
  ui_story_30540601_91_dialog_content = "I'm pretty sure that by \"mediating\", the manual means \"stopping the fight\"...",
  ui_story_30540601_92_dialog_content = "...",
  ui_story_30540601_93_dialog_content = "Look, PlayerName! They're so stunned that they've forgotten all about their argument...",
  ui_story_30540601_94_dialog_content = "That must count as stopping their fight in some way, right?",
  ui_story_30540601_95_dialog_content = "... Anyways, when you said you were inspecting rooms earlier...",
  ui_story_30540601_96_dialog_content = "Did you happen to confiscate Regina's speakers and Barbara's saw while you were at it?",
  ui_story_30540601_97_dialog_content = "I did, in fact, remove two large speakers from the Lounge earlier.",
  ui_story_30540601_98_dialog_content = "As well as a saw, which I found in the corner of the Cafe.",
  ui_story_30540601_99_dialog_content = "I-I didn't forget it there! I just put it down for a little while.",
  ui_story_30540601_100_dialog_content = "Ha? What gives you the right to take my speakers?!",
  ui_story_30540601_101_dialog_content = "The weird pipes sticking out of them shoot out flames! They're entirely too dangerous!",
  ui_story_30540601_102_dialog_content = "But those are a part of my act! They're special effects!",
  ui_story_30540601_103_dialog_content = "Hold on, according to the rule in the manual... Your hairdo is also incredibly dangerous!",
  ui_story_30540601_104_dialog_content = "What kind of rule is that?!",
  ui_story_30540601_105_dialog_content = "When I first came aboard the Colossus, nobody mentioned any rules to me! Why bring them up now, all of a sudden?!",
  ui_story_30540601_106_dialog_content = "P-Please stop fighting! Anyways...",
  ui_story_30540601_107_dialog_content = "Nadine, could you give them back their speaker and saw first, please?",
  ui_story_30540601_108_dialog_content = "But the rules clearly state...",
  ui_story_30540601_109_dialog_content = "These rules have never been officially enforced on the Colossus before.",
  ui_story_30540601_110_dialog_content = "Does that mean... I made a mistake?",
  ui_story_30540601_111_dialog_content = "Not at all! It's just that the rules have to be slightly adjusted depending on the situation. You don't have to stick to them so closely.",
  ui_story_30540601_112_dialog_content = "Very well. You're the Navigator, after all.",
  ui_story_30540601_113_dialog_content = "If you say so, I will naturally follow your orders...",
  ui_story_30540601_114_dialog_content = "So where's our stuff? Hand it over, and we'll put this whole thing behind us.",
  ui_story_30540601_115_dialog_content = "Please come with me. I'll take you there.",
  ui_story_30540601_116_dialog_content = "PlayerName... I made things worse, didn't I?",
  ui_story_30540601_117_dialog_content = "*Ahem* Don't beat yourself up about it.",
  ui_story_30540601_118_dialog_content = "Following the rules as closely and faithfully as you did was commendable, too.",
  ui_story_30540601_119_dialog_content = "Things just got a little out of hand, that's all.",
  ui_story_30540601_120_dialog_content = "Needless to say, I think we should avoid confiscating anyone's stuff from now on.",
  ui_story_30540601_121_dialog_content = "Everyone aboard the Colossus does care about one another, and would never do anything to endanger each other's lives, relatively...",
  ui_story_30540601_122_dialog_content = "Very well, I understand now!",
  ui_story_30540601_123_dialog_content = "Oh! I'm sure you must be thirsty after all that explaining.",
  ui_story_30540601_124_dialog_content = "Would you like something to drink? I can make most things, especially tea and coffee.",
  ui_story_30540601_125_dialog_content = "No thanks, I'm fine.",
  ui_story_30540601_125X1_dialog_content = "But I feel as though I have to do something as an apology... Would you like a shoulder massage then?",
  ui_story_30540601_126_dialog_content = "Uh... M-Maybe a cup of coffee wouldn't hurt... Extra milk and sugar, please!",
  ui_story_30540601_127_dialog_content = "Not a problem! I'll be back with your coffee before you know it!",
  ui_story_30540601_128_dialog_content = "I'm back, PlayerName—",
  ui_story_30540601_129_dialog_content = "\"I love work, yes I do!\"",
  ui_story_30540601_130_dialog_content = "Ahhh!!",
  ui_story_30540601_131_dialog_content = "N-Nadine, are you okay?!",
  ui_story_30540601_132_dialog_content = "I... I'm okay... But your coffee, I...",
  ui_story_30540601_133_dialog_content = "That's not important! Are you hurting anywhere?",
  ui_story_30540601_134_dialog_content = "No, but... My new clothes...",
  ui_story_30540601_135_dialog_content = "I'm sorry! I'll go wash them right now!",
  ui_story_30540601_136_dialog_content = "It's fine, it only got on a small part... *Sigh* She's already gone.",
  ui_story_30540601_137_dialog_content = "Urgh...",
  ui_story_30540601_138_dialog_content = "It's okay, Nadine. The coffee only spilled on a small part of the clothes.",
  ui_story_30540601_139_dialog_content = "But... But I promised I wouldn't get this one dirty!",
  ui_story_30540601_140_dialog_content = "And I also completely failed at <color=#FFB400>patrol duty</color>...",
  ui_story_30540601_141_dialog_content = "They were just little mistakes, Nadine! It's perfectly normal to run into small issues like this.",
  ui_story_30540601_142_dialog_content = "Besides, seeing you fall over and spill drinks on yourself... I've gotten used to it, at least.",
  ui_story_30540601_143_dialog_content = "Huh?! A-Am I... Really that clumsy...?",
  ui_story_30540601_144_dialog_content = "That's not what I mean! What I mean, is that your occasional clumsiness is one of your lovely traits!",
  ui_story_30540601_145_dialog_content = "In any case, you don't need to worry about it.",
  ui_story_30540601_146_dialog_content = "The more you try to console me... The more I feel like I've been letting everybody down.",
  ui_story_30540601_147_dialog_content = "But why? It's just your clothes, after all! Unless... Is that what's bothering you? Getting your clothes dirty?",
  ui_story_30540601_148_dialog_content = "Yes... A uniform is extremely important.",
  ui_story_30540601_149_dialog_content = "For everyone to give me such a nice uniform... They must be expecting me to do an even better job than before.",
  ui_story_30540601_150_dialog_content = "Not at all! Why would you think that?",
  ui_story_30540601_151_dialog_content = "Force of habit, I suppose...",
  ui_story_30540601_152_dialog_content = "*Sigh* You're always talking about work, even when you're not at work...",
  ui_story_30540601_153_dialog_content = "The reason I gave you these clothes was that I thought they really suited you, that's all!",
  ui_story_30540601_154_dialog_content = "Also, I thought that by giving you some more casual and comfortable clothing...",
  ui_story_30540601_155_dialog_content = "You would be able to <color=#FFB400>get away from work and rest</color> a little more.",
  ui_story_30540601_156_dialog_content = "I didn't think you would take patrol duty as seriously as your own job.",
  ui_story_30540601_157_dialog_content = "I see. But this outfit... Is it casual?",
  ui_story_30540601_158_dialog_content = "Uh... Okay, you got me. I'm not entirely sure about that, too...",
  ui_story_30540601_159_dialog_content = "But look! It's light and breathable, and doesn't have any defensive properties at all.",
  ui_story_30540601_160_dialog_content = "It seems a little more relaxed than your usual uniform, right?",
  ui_story_30540601_161_dialog_content = "I-I think so...",
  ui_story_30540601_162_dialog_content = "Anyways, it's great that you're so diligent in whatever you do, but it can also give you a lot of unnecessary stress.",
  ui_story_30540601_163_dialog_content = "Being on-duty is work, don't get me wrong, but as long as you check in regularly and complete patrols on time, that's enough.",
  ui_story_30540601_164_dialog_content = "There's no need to be so serious about it.",
  ui_story_30540601_165_dialog_content = "Now that I'm back and have nothing to do, why don't I show you how to handle patrol duty the right way?",
  ui_story_30540601_166_dialog_content = "Okay!",
  ui_story_30540601_167_dialog_content = "I'm back! Did anything happen while I was gone, Nadine...?",
  ui_story_30540601_168_dialog_content = "\"I love breaks, yes I do!\"",
  ui_story_30540601_169_dialog_content = "\"I love breaks, how 'bout you?\"",
  ui_story_30540601_170_dialog_content = "Why are the Fireflies singing such a weird song? Hang on... Are they dancing?!",
  ui_story_30540601_171_dialog_content = "Welcome back, Miss Vice!",
  ui_story_30540601_172_dialog_content = "Since Vice asked so sincerely...",
  ui_story_30540601_173_dialog_content = "We will answer as truthfully as possible!",
  ui_story_30540601_174_dialog_content = "We're on patrol duty.",
  ui_story_30540601_175_dialog_content = "And since we're on patrol duty...",
  ui_story_30540601_176_dialog_content = "To maintain a peaceful, loving environment aboard the Colossus...",
  ui_story_30540601_177_dialog_content = "We have reprogrammed the Fireflies to play a new song!",
  ui_story_30540601_178_dialog_content = "One that will help everyone enjoy a sense of relaxation!",
  ui_story_30540601_179_dialog_content = "Let's do our best to relax!",
  ui_story_30540601_180_dialog_content = "<color=#e8d9bb>Zoom!</color>",
  ui_story_30540601_181_dialog_content = "... There are so many things wrong with this situation, I don't even know where to start!",
  ui_story_30540602_1_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_30540602_2_dialog_content = "Ahhh—My lantern got blown away!",
  ui_story_30540602_3_dialog_content = "Man, if only I hadn't listened to that peddler! What am I even doing here, messing around in these tide pools?",
  ui_story_30540602_4_dialog_content = "...",
  ui_story_30540602_5_dialog_content = "Hey, I see a light over there! Better go take a look.",
  ui_story_30540602_6_dialog_content = "...",
  ui_story_30540602_7_dialog_content = "Wait, something about that girl holding a lantern seems strangely familiar.",
  ui_story_30540602_8_dialog_content = "It's Nadine! What are you doing here?",
  ui_story_30540602_9_dialog_content = "Navigator! Wait, shouldn't I be asking you the same question?",
  ui_story_30540602_10_dialog_content = "Before that, you should know—",
  ui_story_30540602_11_dialog_content = "The wind and the waves here are really strong, and there aren't many safe places to find your footing.",
  ui_story_30540602_12_dialog_content = "One wrong step and you might end up in the ocean. You should head back as soon as you can.",
  ui_story_30540602_13_dialog_content = "I know, I know. You're as responsible as ever, Nadine.",
  ui_story_30540602_14_dialog_content = "I just never expected to run into you in Twin Pavilions Bay, that's all...",
  ui_story_30540602_15_dialog_content = "And you seem a little different than usual...",
  ui_story_30540602_16_dialog_content = "Could you tell me what you're doing here?",
  ui_story_30540602_17_dialog_content = "You sure are persistent.",
  ui_story_30540602_18_dialog_content = "... I suppose I could tell you about my part-time job—a lantern holder.",
  ui_story_30540602_19_dialog_content = "The most important aspect of my work is... waiting.",
  ui_story_30540602_20_dialog_content = "Waiting?",
  ui_story_30540602_21_dialog_content = "Yes. Do you see the horizon over there? It's probably too dark to see it clearly right now.",
  ui_story_30540602_22_dialog_content = "But there are usually a lot of ships over there. Lots.",
  ui_story_30540602_23_dialog_content = "Merchant ships traveling north and south, fishing vessels hauling huge catches, and tour boats carrying excited passengers.",
  ui_story_30540602_24_dialog_content = "My colleague from the previous work shift says that visitors often chant poems as they appreciate the views here.",
  ui_story_30540602_25_dialog_content = "It must be very soothing for both the mind and spirit.",
  ui_story_30540602_26_dialog_content = "So, you're waiting for those ships?",
  ui_story_30540602_27_dialog_content = "Yes. My job is to await the return of every ship that departs from here.",
  ui_story_30540602_28_dialog_content = "And when the weather is especially bad, it's also my job to light their way to safety!",
  ui_story_30540602_29_dialog_content = "Which is all the more reason you should go back now, Navigator. It's dangerous to be out and about in this weather.",
  ui_story_30540602_30_dialog_content = "A storm might even be brewing...",
  ui_story_30540602_31_dialog_content = "Why don't you come with me, Nadine? If the weather's this bad, you probably shouldn't be working either.",
  ui_story_30540602_32_dialog_content = "I can't leave. Not yet.",
  ui_story_30540602_33_dialog_content = "I'm still waiting for something...",
  ui_story_30540602_34_dialog_content = "Waiting for what?",
  ui_story_30540602_35_dialog_content = "For the sounds of those ships coming back to port.",
  ui_story_30540602_36_dialog_content = "... Have you ever experienced anything like this, Navigator?",
  ui_story_30540602_37_dialog_content = "When you spend an entire day in a complete state of focus, you start to notice all kinds of sounds.",
  ui_story_30540602_38_dialog_content = "Like hearing the birds flying through the clouds?",
  ui_story_30540602_39_dialog_content = "Yes, something like that.",
  ui_story_30540602_40_dialog_content = "When I working this reef, watching all those boats come and go...",
  ui_story_30540602_41_dialog_content = "The waves bring me stories from the ships at sea.",
  ui_story_30540602_42_dialog_content = "That's pretty unusual...",
  ui_story_30540602_43_dialog_content = "One time, I heard about how a fishing boat capsized and its crew was tossed into the sea.",
  ui_story_30540602_44_dialog_content = "Thankfully, a nearby rescue boat showed up and pulled everyone out of the water.",
  ui_story_30540602_45_dialog_content = "When the fishermen finally came ashore, their wives reacted in all kinds of ways.",
  ui_story_30540602_46_dialog_content = "Some of them hugged their husbands and cried, while others dragged them home by the ear.",
  ui_story_30540602_47_dialog_content = "I see... Stories like that are just like clouds: they come in all shapes and sizes.",
  ui_story_30540602_48_dialog_content = "They can tell you a lot about the world around us, and how quickly things can change.",
  ui_story_30540602_49_dialog_content = "Indeed... Well, the wind is getting stronger. A raging storm must be underway now.",
  ui_story_30540602_50_dialog_content = "Are you sure you don't want to go back? There's still time, you know...",
  ui_story_30540602_51_dialog_content = "I'll be fine. Tell me another story you heard from the sea!",
  ui_story_30540602_52_dialog_content = "It'll help us pass the time!",
  ui_story_30540602_53_dialog_content = "The ocean's stories are all mostly the same. I don't think people would really care to listen to them.",
  ui_story_30540602_54_dialog_content = "Why don't I tell you a story that was told to me by someone else? My colleague, to be precise.",
  ui_story_30540602_55_dialog_content = "On the shores of a faraway land, there is a stone tower in the shape of a lotus.",
  ui_story_30540602_56_dialog_content = "At the foot of this tower are countless, tiny lions that are also made of stone.",
  ui_story_30540602_57_dialog_content = "This distant tower isn't particularly tall or beautiful. It emits no golden radiance, either.",
  ui_story_30540602_58_dialog_content = "Nevertheless, it holds a special place in the hearts of those who live nearby. Whenever it sustains damage, someone will inevitably fix it.",
  ui_story_30540602_59_dialog_content = "Even to this day, it stands proudly at the edge of the sea. Over the years, people have stood atop the tower with lanterns in hand, just like me...",
  ui_story_30540602_60_dialog_content = "Guiding wayward ships to safety for countless centuries.",
  ui_story_30540602_61_dialog_content = "... I've always been fond of this story, mostly because I also carry a lantern wherever I go.",
  ui_story_30540602_62_dialog_content = "I want to keep lighting the way for others, if only for just a little longer.",
  ui_story_30540602_63_dialog_content = "... The wind is getting even worse, Navigator... Will you be able to stay on your feet?",
  ui_story_30540602_64_dialog_content = "I'll be fine.",
  ui_story_30540602_65_dialog_content = "Then I suggest you find better footing. Once the rain begins to fall, I might not be able to save you.",
  ui_story_30540602_66_dialog_content = "Don't worry, I'll think of something if things really get bad.",
  ui_story_30540602_67_dialog_content = "If you're done with your story, I'd like to share one of my own.",
  ui_story_30540602_68_dialog_content = "Once, there was a traveler who arrived on the shores of Twin Pavilions Bay. While observing the tide pools, he met a young girl from Lumopolis.",
  ui_story_30540602_69_dialog_content = "She was dressed in the fashion of Twin Pavilions Bay. As she walked along the seashore, she held a lantern in her hands.",
  ui_story_30540602_70_dialog_content = "A storm was coming, but she refused to leave her post atop a huge reef.",
  ui_story_30540602_71_dialog_content = "She listened to the waves as she waited for the ships to come home.",
  ui_story_30540602_72_dialog_content = "There were no lighthouses here, making her duties especially important in the face of the approaching storm—a protector she is.",
  ui_story_30540602_73_dialog_content = "She wasn't just protecting the ships at sea, but also any lost tide poolers who appeared on the beach!",
  ui_story_30540602_74_dialog_content = "Are you...",
  ui_story_30540602_75_dialog_content = "Are you complimenting me right now?",
  ui_story_30540602_76_dialog_content = "I don't think anyone has ever acknowledged my work like this!",
  ui_story_30540602_77_dialog_content = "I'm pretty sure everyone feels that way about your work, even if they don't say it.",
  ui_story_30540602_78_dialog_content = "Listening to the boats coming and going and illuminating their way home...",
  ui_story_30540602_79_dialog_content = "You're just as important as a lighthouse in their eyes!",
  ui_story_30540602_80_dialog_content = "The rain is starting to fall.",
  ui_story_30540602_81_dialog_content = "Are you absolutely sure you don't want to go back, Navigator?",
  ui_story_30540602_82_option_content = "Do you really have to ask?",
  ui_story_30540602_83_option_content = "Can't leave the lighthouse unattended, can I?",
  ui_story_30540602_84_dialog_content = "Navigator... Thank you.",
  ui_story_30540602_85_dialog_content = "I want to try something.",
  ui_story_30540602_86_dialog_content = "To use my power to help as many people as possible, even if it's just a single, lost beachgoer!",
  ui_story_30540602_87_dialog_content = "Light... gather now.",
  ui_story_30540602_88_dialog_content = "Under the lantern!",
  ui_story_30540602_89_dialog_content = "The skies are clearing up.",
  ui_story_30540602_90_dialog_content = "Achoo! Ugh, I think I may have caught a cold.",
  ui_story_30540602_91_dialog_content = "Makes sense, since we stayed out in the heavy rain for so long.",
  ui_story_30540602_92_dialog_content = "Still, we must've helped some people who were caught out at sea, right?",
  ui_story_30540602_93_dialog_content = "I'm sure we did. After all, the sea looks much less sad now.",
  ui_story_30540602_94_dialog_content = "The sea is live. That's something I'll always remember when it looks sad.",
  ui_story_30540602_95_dialog_content = "That's why I want to raise my lantern even higher. As high as a lighthouse.",
  ui_story_30540602_96_dialog_content = "You can do it, Nadine! So can we head back now?",
  ui_story_30540602_97_dialog_content = "Yes. Once we get back to the city, I'll put on some dry clothes and take a nice, long nap...",
  ui_story_30540602_98_dialog_content = "Wait! I still have to show up for work today!",
  ui_story_30540602_99_dialog_content = "Oh no, what time is it...?",
  ui_story_30540602_100_dialog_content = "Huh? You mean you're doing this on top of your usual Lumopolis work?!",
  ui_story_30540602_101_dialog_content = "That's way too much, even for you! You should call in sick!",
  ui_story_30540602_102_dialog_content = "I-I can't! Work is work. Calling off would be no different than shirking my duties! I have to... Achoo!",
  ui_story_30540602_103_dialog_content = "Achoo! Achoo! Achoo!",
  ui_story_30540602_104_dialog_content = "Go back and get some rest right now, Nadine!",
  ui_story_30540602_105_dialog_content = "But my work...",
  ui_story_30540602_106_dialog_content = "Achoo!"
}
return config
